import * as THREE from 'three/webgpu';
import { texture, uv, uniform, vec4, mix, float } from 'three/tsl';
import { gsap } from 'gsap';
import { fontAtlasText } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-journal-quote-panel';
  group.position.set(2.5, 0.7000000000000001, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const colors = {
    ink: new THREE.Color('#16161d'),
    paper: new THREE.Color('#e8ecf2'),
    accent: new THREE.Color('#ff2a38'),
    surface: new THREE.Color('#0b0b10'),
  };

  const width = 2.2;
  const height = (320 / 512) * width;

  const map = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const hoverUniform = uniform(0);
  const focusUniform = uniform(0);

  const texColor = texture(map, uv());
  const tintedColor = mix(texColor, vec4(colors.surface, 1.0), float(0.05));
  const accentEdge = mix(tintedColor, vec4(colors.accent, 1.0), focusUniform.mul(0.15));

  material.colorNode = mix(accentEdge, tintedColor.mul(1.08), hoverUniform.mul(0.3));

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'quote-panel-plane';
  group.add(plane);

  // Attribution text (client quote + attribution line) rendered via MSDF font atlas
  const quoteText = fontAtlasText({
    text: '"An object of quiet, engineered permanence."',
    font: 'Lora',
    weight: 400,
    size: 0.13,
    color: colors.paper,
    maxWidth: width * 0.85,
    align: 'center',
    atlas: ctx.fontAtlas,
  });
  quoteText.position.set(0, height * 0.18, 0.01);
  group.add(quoteText);

  const attributionText = fontAtlasText({
    text: '— M. Aldric, Collector',
    font: 'JetBrains Mono',
    weight: 700,
    size: 0.09,
    color: colors.accent,
    maxWidth: width * 0.8,
    align: 'center',
    atlas: ctx.fontAtlas,
  });
  attributionText.position.set(0, -height * 0.22, 0.01);
  group.add(attributionText);

  // Apply cinematic primitives declared in config
  if (ctx.primitives && ctx.primitives['parallax-scroll']) {
    ctx.primitives['parallax-scroll'](group, { intensity: 0.25, trigger: 'scroll' });
  }

  const timelines = [];

  const baseY = group.position.y;

  function onHover() {
    focusUniform.value = 0;
    const tl = gsap.timeline();
    tl.to(hoverUniform, { value: 1, duration: 0.7, ease: 'power3.out' });
    tl.to(group.position, { y: baseY + 0.15, duration: 0.7, ease: 'power3.out' }, 0);
    timelines.push(tl);
  }

  function onHoverOut() {
    const tl = gsap.timeline();
    tl.to(hoverUniform, { value: 0, duration: 0.5, ease: 'power2.out' });
    tl.to(group.position, { y: baseY, duration: 0.5, ease: 'power2.out' }, 0);
    timelines.push(tl);
  }

  function onClick() {
    const tl = gsap.timeline();
    tl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' });
    tl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.2, ease: 'back.out' });
    timelines.push(tl);

    focusUniform.value = 1;

    if (group.userData.emit) {
      group.userData.emit('hub-journal.select', { source: 'quote-panel' });
    }
  }

  group.userData.handlers = {
    hover: onHover,
    hoverOut: onHoverOut,
    click: onClick,
  };

  group.userData.cleanup = function cleanup() {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    if (quoteText && quoteText.userData && quoteText.userData.cleanup) {
      quoteText.userData.cleanup();
    }
    if (attributionText && attributionText.userData && attributionText.userData.cleanup) {
      attributionText.userData.cleanup();
    }
  };

  return group;
}
